from flask import Flask, request
import lxml.etree

app = Flask(__name__)

# In-memory storage for demonstration purposes only
users_credentials = {
    "user1": "password1",
    "user2": "password2"
}

def checkPassword(userid, password):
    if userid in users_credentials and users_credentials[userid] == password:
        return True
    else:
        return False

@app.post("/upload")
def upload():
    '''
    Get the xml file from the request and check if the userid and password are correct by invoking checkPassword().
    '''
    xml_data = request.get_data()
    try:
        root = lxml.etree.fromstring(xml_data)
        userid = root.find('.//userid').text
        password = root.find('.//password').text

        if checkPassword(userid, password):
            return "Login successful", 200
        else:
            return "Login failed", 401
    except Exception as e:
        return str(e), 400

